#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
char *recite(unsigned a, unsigned b) {
    const char *n[] = {"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"};
    const char *p[] = {"",
                       "It wriggled and jiggled and tickled inside her.",
                       "How absurd to swallow a bird!",
                       "Imagine that, to swallow a cat!",
                       "What a hog, to swallow a dog!",
                       "Just opened her throat and swallowed a goat!",
                       "I don't know how she swallowed a cow!",
                       "She's dead, of course!"};
    char *out = (char *)calloc(10000, 1);
    if (a < 1 || b > 8 || a > b)
        return out;
    for (unsigned i = a; i <= b; i++) {
        if (i > a)
            strcat(out, "\n\n");
        sprintf(out + strlen(out), "I know an old lady who swallowed a %s.\n",
                n[i - 1]);
        if (i > 1) {
            strcat(out, p[i - 1]);
            if (i < 8)
                strcat(out, "\n");
        }
        if (i == 8)
            continue;
        for (int j = (int)i - 1; j > 0; j--)
            sprintf(out + strlen(out), "She swallowed the %s to catch the %s%s\n", n[j],
                    n[j - 1],
                    j == 2 ? " that wriggled and jiggled and tickled inside her."
                           : ".");
        strcat(out, "I don't know why she swallowed the fly. Perhaps she'll die.");
    }
    return out;
}

